{
 "cases": [
  {
   "name": "model 不支持",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": {
    "model": "qwen-backup",
    "messages": [
     {
      "role": "user",
      "content": "你好"
     }
    ],
    "temperature": 3
   },
   "raw_body": null,
   "expect_status": 404,
   "expect_code": "model_not_found"
  },
  {
   "name": "model 不存在",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": {
    "model": "qwen-vl",
    "messages": [
     {
      "role": "user",
      "content": "你好"
     }
    ],
    "temperature": 3
   },
   "raw_body": null,
   "expect_status": 404,
   "expect_code": "model_not_allowed"
  },
  {
   "name": "model 类型和接口不匹配",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": {
    "model": "embed-mini",
    "messages": [
     {
      "role": "user",
      "content": "你好"
     }
    ],
    "temperature": 3
   },
   "raw_body": null,
   "expect_status": 400,
   "expect_code": "model_kind_mismatch"
  },
  {
   "name": "max_tokens 大于 4096",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": {
    "model": "qwen-mini",
    "messages": [
     {
      "role": "user",
      "content": "你好"
     }
    ],
    "temperature": 3,
    "max_tokens": 4097
   },
   "raw_body": null,
   "expect_status": 400,
   "expect_code": "invalid_parameter"
  },
  {
   "name": "消息中包含拦截词",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": {
    "model": "qwen-mini",
    "messages": [
     {
      "role": "user",
      "content": "你好，我不能处理这个请求。"
     }
    ],
    "temperature": 3,
    "max_tokens": 4096
   },
   "raw_body": null,
   "expect_status": 400,
   "expect_code": "content_filter"
  },
  {
   "name": "非法 input",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": {
    "model": "qwen-mini",
    "messages": [
     {
      "role": "user",
      "content": "你好"
     }
    ],
    "temperature": 3,
    "max_tokens": 4096,
    "stop": "违禁词示例"
   },
   "raw_body": null,
   "expect_status": 400,
   "expect_code": "invalid_parameter"
  },
  {
   "name": "非法 input 重复",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": {
    "model": "qwen-mini",
    "messages": [
     {
      "role": "user",
      "content": "你好"
     },
     {
      "role": "assistant",
      "content": "你好"
     }
    ],
    "temperature": 3,
    "max_tokens": 4096,
    "stop": "违禁词示例"
   },
   "raw_body": null,
   "expect_status": 400,
   "expect_code": "invalid_parameter"
  },
  {
   "name": "非法 input 重复",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": {
    "model": "qwen-mini",
    "messages": [
     {
      "role": "user",
      "content": "你好"
     },
     {
      "role": "assistant",
      "content": "你好"
     }
    ],
    "temperature": 3,
    "max_tokens": 4096,
    "stop": "违禁词示例"
   },
   "raw_body": null,
   "expect_status": 400,
   "expect_code": "invalid_parameter"
  },
  {
   "name": "非法 input 重复",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": {
    "model": "qwen-mini",
    "messages": [
     {
      "role": "user",
      "content": "你好"
     },
     {
      "role": "assistant",
      "content": "你好"
     }
    ],
    "temperature": 3,
    "max_tokens": 4096,
    "stop": "违禁词示例"
   },
   "raw_body": null,
   "expect_status": 400,
   "expect_code": "invalid_parameter"
  }
 ]
